258	describe('FsArtifactStore', () => {
259	  // POSIX permits replacement while the destination is open; this exercises Windows sharing.
260	  it.skipIf(process.platform !== 'win32')(
261	    'accepts verified bytes published by another writer while a read handle blocks replacement',
262	    async () => {
263	      const content = 'x'.repeat(32 * 1024 * 1024);
264	      const bytes = Buffer.from(content);
265	      const hash = createHash('sha256').update(bytes).digest('hex');
266	      const ref = `artifact:transcript/${hash}`;
267	      const dir = join(dataDir, 'artifacts', 'transcript');
268	      const final = join(dir, hash);
269	      mkdirSync(dir, { recursive: true });
270	      let readHandle: number | undefined;
271	      let injected = false;
272	      let setupError: unknown;
273	      const observer = watch(dir, (_event, name) => {
274	        if (injected || !name?.startsWith(`.${hash}.`) || !name.endsWith('.tmp')) return;
275	        injected = true;
276	        try {
277	          // A .tmp proves put already checked the missing destination. Synchronous setup keeps
278	          // this callback ahead of put's remaining asynchronous write/fsync/rename continuations.
279	          statSync(join(dir, name));
280	          writeFileSync(final, bytes);
281	          readHandle = openSync(final, 'r');
282	        } catch (error) {
283	          setupError = error;
284	        }
285	      });
286	      const store = new FsArtifactStore(dataDir);
287	      try {
288	        await expect(store.put('transcript', content)).resolves.toEqual({
289	          ref,
290	          bytes: bytes.length,
291	        });
292	        expect(injected).toBe(true);
293	        expect(setupError).toBeUndefined();
294	        expect(readHandle).toBeDefined();
295	        expect(await store.get(ref)).toBe(content);
296	        expect(readFileSync(final).equals(bytes)).toBe(true);
297	        expect(readdirSync(dir)).toEqual([hash]);
298	      } finally {
299	        observer.close();
300	        if (readHandle !== undefined) closeSync(readHandle);
301	      }
302	    },
303	  );
304	
305	  it('rejects corrupted final bytes and atomically repairs a pre-existing partial file', async () => {
306	    const store = new FsArtifactStore(dataDir);
307	    const content = 'complete transcript: 世界 🧙';
308	    const hash = createHash('sha256').update(content).digest('hex');
309	    const dir = join(dataDir, 'artifacts', 'transcript');
310	    mkdirSync(dir, { recursive: true });
311	    writeFileSync(join(dir, hash), 'complete');
312	    const ref = `artifact:transcript/${hash}`;
