314	    const repaired = await store.put('transcript', content);
315	    expect(repaired.ref).toBe(ref);
316	    expect(readFileSync(join(dir, hash)).equals(Buffer.from(content))).toBe(true);
317	    expect(await store.get(ref)).toBe(content);
318	    expect(readdirSync(dir)).toEqual([hash]);
319	  });
