322	    const store = new FsArtifactStore(dataDir);
323	    const { ref } = await store.put('transcript', 'a complete transcript');
324	    const hash = ref.split('/')[1]!;
325	    writeFileSync(join(dataDir, 'artifacts', 'transcript', hash), 'a');
