330	  it('ignores interrupted temporary writes and converges under identical and different concurrent puts', async () => {
331	    const store = new FsArtifactStore(dataDir);
332	    const dir = join(dataDir, 'artifacts', 'transcript');
333	    mkdirSync(dir, { recursive: true });
334	    writeFileSync(join(dir, '.interrupted.tmp'), 'partial');
335	    const contents = ['', '世界 🧙\u0000\r\n'.repeat(200_000), 'other content'];
336	    const stored = await Promise.all(
337	      contents.flatMap((content) => [
338	        store.put('transcript', content),
339	        new FsArtifactStore(dataDir).put('transcript', content),
340	      ]),
341	    );
342	    for (const [i, content] of contents.entries()) {
343	      const a = stored[i * 2]!;
344	      expect(stored[i * 2 + 1]).toEqual(a);
345	      expect(a.bytes).toBe(Buffer.byteLength(content));
346	      expect(await store.get(a.ref)).toBe(content);
347	      expect(await store.get(a.ref.toUpperCase())).toBeUndefined();
348	      expect(readFileSync(join(dir, a.ref.split('/')[1]!)).equals(Buffer.from(content))).toBe(true);
349	    }
350	    expect(new Set(stored.map((item) => item.ref)).size).toBe(contents.length);
351	    expect(readdirSync(dir).sort()).toEqual(
352	      [
353	        '.interrupted.tmp',
354	        ...stored.filter((_, i) => i % 2 === 0).map((item) => item.ref.split('/')[1]!),
355	      ].sort(),
356	    );
357	  });
