362	    const second = await store.put('Transcript', 'hello world');
363	    expect(first.ref).toBe(second.ref);
364	    expect(first.ref).toMatch(/^artifact:transcript\/[a-f0-9]{64}$/);
365	    expect(first.bytes).toBe(11);
