382	    const store = new FsArtifactStore(dataDir);
383	    writeFileSync(join(dataDir, 'artifacts'), 'a file blocks the artifact directory');
384	    await expect(store.put('transcript', 'complete')).rejects.toMatchObject({
385	      code: 'ARTIFACT_WRITE_FAILED',
386	    });
387	  });
388	
389	  it('returns undefined for malformed or missing references', async () => {
390	    const store = new FsArtifactStore(dataDir);
391	    expect(await store.get('nope')).toBeUndefined();
392	    expect(await store.get('artifact:transcript/../../etc/passwd')).toBeUndefined();
393	    expect(await store.get(`artifact:transcript/${'a'.repeat(64)}`)).toBeUndefined();
394	  });
395	
396	  it('rethrows unexpected filesystem errors', async () => {
397	    const store = new FsArtifactStore(dataDir);
398	    const { ref } = await store.put('kind', 'content');
399	    const hash = ref.split('/')[1] as string;
400	    // Make the expected file path a directory so reading it fails with something other than ENOENT.
401	    rmSync(join(dataDir, 'artifacts', 'kind', hash));
402	    const { mkdirSync } = await import('node:fs');
403	    mkdirSync(join(dataDir, 'artifacts', 'kind', hash));
404	    await expect(store.get(ref)).rejects.toThrow();
405	  });
406	});
